// SYCL port of localcorr_cuda_pyramid_kernel.cu (forward path), produced
// with the Intel DPC++ Compatibility Tool (dpct) and then reworked by
// hand:
//
// - The CUDA __shfl_xor_sync butterfly reductions were replaced with
//   sycl::reduce_over_group on the sub-group. The Intel OpenCL CPU
//   runtime of oneAPI 2026.1 crashes on the SPIR-V non-uniform shuffle
//   ops generated by sycl::permute_group_by_xor, while group reductions
//   work on both the CPU and the GPU, so reductions are the only
//   cross-lane communication used here.
// - The half-precision fast paths compute in float (loads and stores
//   still use fp16), which is simpler and more accurate than the
//   __half2 arithmetic of the CUDA version.
// - The VEC/CITER channel templating of the CUDA fast paths was collapsed
//   into a runtime channel count with compile-time register-array buckets
//   (4/8/16 channels per lane). This cuts the number of generated kernel
//   instantiations from ~600 to ~50 so that the runtime JIT (and IGC on
//   Intel GPUs) stays fast and robust; the build additionally splits the
//   device code per kernel so only the launched kernels are JIT-compiled.
// - The 8-lane-per-pixel fast path and the generic-radius kernel of the
//   CUDA version were dropped: the warp-per-pixel fast path covers every
//   C divisible by 32 up to 512 channels, and the any-C fallback kernel
//   (runtime radius/dilation, shared-memory staging) covers everything
//   else, including C not divisible by 32 and dilation > 1.
//
// The file is compiled together with localcorr_sycl_ov_extension.cpp
// into one shared library (see build.sh) that OpenVINO loads as a custom
// operation extension.

#include "localcorr_cuda_pyramid_kernel.h"

#include <cstdint>
#include <cstdio>

#define LCORR_WARP_SIZE 32
#define LCORR_WARPS_PER_BLOCK 4
#define LCORR_THREADS_PER_BLOCK (LCORR_WARPS_PER_BLOCK * LCORR_WARP_SIZE)

#define LCORR_MAX_LEVELS 8
#define LCORR_MAX_RADIUS 4

// Width of the vec used for the batched displacement-row reduction; RD =
// 2*RADIUS+1 <= 9 always fits.
#define LCORR_RED_VEC 16

// Maximum channels per lane of the fast path (C/32).
#define LCORR_NELEM_MAX 16


// ---------------------------------------------------------------------------
// Fast path: one warp per output pixel, lanes split the channels (NELEM =
// C/32, bounded by LCORR_NELEM_MAX), compile-time RADIUS. fmap1 and the
// sliding bilinear corner window live in registers; a whole displacement
// row is reduced with one batched sub-group reduction of a float vector.
// Requires C % 32 == 0, radius in [1, 4] and dilation == 1.
// ---------------------------------------------------------------------------
template <typename scalar_t, int NMAX, int RADIUS, bool YMAJOR>
void localcorr_pyramid_kernel(
    sycl::nd_item<3> item_ct1,
    const scalar_t *__restrict__ fmap1,        // [B, H1, W1, C]
    const scalar_t *__restrict__ fmap2_packed, // [B, C*sum_i h_i*w_i]
    const scalar_t *__restrict__ coords,       // [B, 2, H1, W1] (x, y)
    scalar_t *__restrict__ corr,               // [B, levels, RD*RD, H1, W1]
    int H1, int W1, int C, int levels) {
  constexpr int RD = 2 * RADIUS + 1;
  constexpr int RD2 = RD * RD;

  const int b = item_ct1.get_group(1);
  const int warp = item_ct1.get_local_id(2) >> 5;
  const int lane = item_ct1.get_local_id(2) & (LCORR_WARP_SIZE - 1);
  const int HW = H1 * W1;
  const int p =
      item_ct1.get_group(2) * LCORR_WARPS_PER_BLOCK + warp; // 1 pixel/warp
  const bool valid = p < HW;
  const int NELEM = C / LCORR_WARP_SIZE; // channels per lane (runtime)

  // Per-level sizes of the packed fmap2 buffer (batch-major layout:
  // [B, C*sum_i h_i*w_i], level i of batch b at b*P + C*sum_{j<i} h_j*w_j).
  int64_t f2_batch_elems = 0;
  {
    int lh = H1, lw = W1;
    for (int i = 0; i < levels; ++i) {
      f2_batch_elems += (int64_t)C * lh * lw;
      lh >>= 1;
      lw >>= 1;
    }
  }
  const scalar_t *f2_lvl = fmap2_packed + (int64_t)b * f2_batch_elems;
  int lvl_h = H1;
  int lvl_w = W1;

  // ---- Load fmap1 for this pixel into registers (float math). ----
  float f1_reg[NMAX];
  if (valid) {
    const int h1 = p / W1;
    const int w1 = p - h1 * W1;
    const scalar_t *f1ptr =
        fmap1 + (((int64_t)b * H1 + h1) * W1 + w1) * C + lane * NELEM;
    #pragma unroll
    for (int i = 0; i < NMAX; ++i)
      f1_reg[i] = (i < NELEM) ? static_cast<float>(f1ptr[i]) : 0.f;
  } else {
    #pragma unroll
    for (int i = 0; i < NMAX; ++i) f1_reg[i] = 0.f;
  }

  // Level-0 coordinates of this pixel.
  float cx = 0.f, cy = 0.f;
  if (valid) {
    const scalar_t *cptr = coords + ((int64_t)b * 2 * HW) + p;
    cx = static_cast<float>(cptr[0]);   // x
    cy = static_cast<float>(cptr[HW]);  // y
  }

  for (int lvl = 0; lvl < levels; ++lvl) {
    // Level coordinates are halved every level.
    const float clx = cx / (float)(1 << lvl);
    const float cly = cy / (float)(1 << lvl);

    const int H2 = lvl_h;
    const int W2 = lvl_w;

    const float x0f = sycl::floor((float)clx);
    const float y0f = sycl::floor((float)cly);
    const float dx = clx - x0f;
    const float dy = cly - y0f;
    const int xb = static_cast<int>(x0f) - RADIUS;
    const int yb = static_cast<int>(y0f) - RADIUS;

    const float wa = (1.f - dx) * (1.f - dy);
    const float wb = dx * (1.f - dy);
    const float wc = (1.f - dx) * dy;
    const float wd = dx * dy;

    scalar_t *out_lvl = corr + ((int64_t)b * levels + lvl) * RD2 * HW;

    // Predicated corner load: column x of row `row` (or zeros) into the
    // NELEM channels of this lane.
    auto loadCorner = [&](int64_t row, int x, bool vy, bool vx, float *fa) {
      if (vy && vx) {
        const scalar_t *q = f2_lvl + (row + x) * C + lane * NELEM;
        #pragma unroll
        for (int i = 0; i < NMAX; ++i)
          fa[i] = (i < NELEM) ? static_cast<float>(q[i]) : 0.f;
      } else {
        #pragma unroll
        for (int i = 0; i < NMAX; ++i) fa[i] = 0.f;
      }
    };

    #pragma unroll
    for (int iy = 0; iy < RD; ++iy) {
      const int y0 = yb + iy;
      const int y1 = y0 + 1;
      const bool vy0 = y0 >= 0 && y0 < H2;
      const bool vy1 = y1 >= 0 && y1 < H2;
      const int64_t row0 = vy0 ? (int64_t)y0 * W2 : 0;
      const int64_t row1 = vy1 ? (int64_t)y1 * W2 : 0;

      // Corner windows: a/c = column x0 (rows y0/y1), b/d = column x1.
      float ca_a[NMAX], cb_a[NMAX], cc_a[NMAX], cd_a[NMAX];
      const bool vx0 = xb >= 0 && xb < W2;
      const bool vx1 = xb + 1 >= 0 && xb + 1 < W2;
      loadCorner(row0, xb, vy0, vx0, ca_a);
      loadCorner(row1, xb, vy1, vx0, cc_a);
      loadCorner(row0, xb + 1, vy0, vx1, cb_a);
      loadCorner(row1, xb + 1, vy1, vx1, cd_a);

      // Per-displacement partial dot products of this window row,
      // batched in one float vector.
      sycl::vec<float, LCORR_RED_VEC> vrow(0.f);

      #pragma unroll
      for (int ix = 0; ix < RD; ++ix) {
        float sum = 0.f;
        #pragma unroll
        for (int i = 0; i < NMAX; ++i) {
          const float f2v = wa * ca_a[i] + wb * cb_a[i] + wc * cc_a[i] +
                            wd * cd_a[i];
          sum = sycl::fma(f1_reg[i], f2v, sum);
        }
        vrow[ix] = sum;

        // Slide the window (the x1 corners become the next x0 corners) and
        // prefetch the next x1 column (1-deep prefetch).
        #pragma unroll
        for (int i = 0; i < NMAX; ++i) {
          ca_a[i] = cb_a[i];
          cc_a[i] = cd_a[i];
        }
        const int xnext = xb + ix + 2;
        const bool vxn = xnext >= 0 && xnext < W2;
        loadCorner(row0, xnext, vy0, vxn, cb_a);
        loadCorner(row1, xnext, vy1, vxn, cd_a);
      }

      // One batched sub-group reduction of the whole row; afterwards every
      // lane holds the reduced partials of all displacements of the row.
      const auto red = sycl::reduce_over_group(
          item_ct1.get_sub_group(), vrow,
          sycl::plus<sycl::vec<float, LCORR_RED_VEC>>());

      // Displacement index: d = iy + rd*ix (YMAJOR: d = ix + rd*iy).
      if (valid && lane < RD) {
        const int d = YMAJOR ? (lane + RD * iy) : (iy + RD * lane);
        out_lvl[(int64_t)d * HW + p] = static_cast<scalar_t>(red[lane]);
      }
    }

    // Advance to the next level in the packed buffer.
    if (lvl + 1 < levels) {
      f2_lvl += (int64_t)C * lvl_h * lvl_w;
      lvl_h >>= 1;
      lvl_w >>= 1;
    }
  }
}


// ---------------------------------------------------------------------------
// Backward kernel (any C / radius / dilation, all levels fused in one
// launch): one warp per output pixel, lanes stride the channels. fmap1
// and the fmap1 gradient accumulators are staged in shared memory as
// float; the scattered fmap2 gradients are accumulated with global fp32
// atomics (the buffer must be zero-initialized; for f16 inputs it is an
// fp32 shadow buffer). Coordinates gradients are not computed (RAFT
// detaches coords). No cross-lane communication is needed, so the
// kernel works with any sub-group size.
// ---------------------------------------------------------------------------
template <typename scalar_t, bool YMAJOR = false>
void localcorr_pyramid_backward_kernel(
    sycl::nd_item<3> item_ct1,
    const scalar_t *__restrict__ fmap1,        // [B, H1, W1, C]
    const scalar_t *__restrict__ fmap2_packed, // [B, C*sum_i h_i*w_i]
    const scalar_t *__restrict__ coords,       // [B, 2, H1, W1] (x, y)
    const scalar_t *__restrict__ corr_grad,    // [B, levels, RD*RD, H1, W1]
    scalar_t *__restrict__ fmap1_grad,         // [B, H1, W1, C]
    float *__restrict__ fmap2_grad,            // [B, C*sum_i h_i*w_i] f32
    int H1, int W1, int C, int r, int levels, int dil, uint8_t *dpct_local) {
  auto smem = (float *)dpct_local;
  const int rd = 2 * r + 1;
  const int RD2 = rd * rd;
  constexpr int LCORR_PIXELS_PER_BLOCK =
      LCORR_WARPS_PER_BLOCK; // 1 pixel per warp
  float *f1_s = smem;                        // [PIXELS, C]
  float *f1g_s = smem + LCORR_PIXELS_PER_BLOCK * C; // [PIXELS, C]

  const int b = item_ct1.get_group(1);
  const int warp = item_ct1.get_local_id(2) >> 5;
  const int lane = item_ct1.get_local_id(2) & (LCORR_WARP_SIZE - 1);
  const int HW = H1 * W1;
  const int p0 = item_ct1.get_group(2) * LCORR_PIXELS_PER_BLOCK;
  const int npix = sycl::min(LCORR_PIXELS_PER_BLOCK, HW - p0);

  // Stage fmap1 for the pixels of this block (converted to float) and
  // zero the gradient accumulators.
  for (int i = item_ct1.get_local_id(2); i < LCORR_PIXELS_PER_BLOCK * C;
       i += LCORR_THREADS_PER_BLOCK) {
    const int q = i / C;
    const int cc = i - q * C;
    float v = 0.f;
    if (q < npix) {
      const int pq = p0 + q;
      const int hq = pq / W1;
      const int wq = pq - hq * W1;
      v = static_cast<float>(
          fmap1[(((int64_t)b * H1 + hq) * W1 + wq) * C + cc]);
    }
    f1_s[i] = v;
    f1g_s[i] = 0.f;
  }
  item_ct1.barrier();

  int64_t f2_batch_elems = 0;
  {
    int lh = H1, lw = W1;
    for (int i = 0; i < levels; ++i) {
      f2_batch_elems += (int64_t)C * lh * lw;
      lh >>= 1;
      lw >>= 1;
    }
  }
  const scalar_t *f2_lvl = fmap2_packed + (int64_t)b * f2_batch_elems;
  float *f2g_lvl = fmap2_grad + (int64_t)b * f2_batch_elems;
  int lvl_h = H1;
  int lvl_w = W1;

  for (int lvl = 0; lvl < levels; ++lvl) {
    const int H2 = lvl_h;
    const int W2 = lvl_w;
    const int p = p0 + warp; // LCORR_PIXELS_PER_WARP == 1

    if (p < HW) {
      const int q = warp;
      const float *f1w = f1_s + q * C;
      float *f1gw = f1g_s + q * C;
      const scalar_t *lvl_base =
          corr_grad + ((int64_t)b * levels + lvl) * RD2 * HW;

      const scalar_t *cptr = coords + ((int64_t)b * 2 * HW) + p;
      const float clx = static_cast<float>(cptr[0]) / (float)(1 << lvl);
      const float cly = static_cast<float>(cptr[HW]) / (float)(1 << lvl);

      const float x0f = sycl::floor((float)clx);
      const float y0f = sycl::floor((float)cly);
      const float dx = clx - x0f;
      const float dy = cly - y0f;
      const int xb = static_cast<int>(x0f) - r * dil;
      const int yb = static_cast<int>(y0f) - r * dil;

      const float wa = (1.f - dx) * (1.f - dy);
      const float wb = dx * (1.f - dy);
      const float wc = (1.f - dx) * dy;
      const float wd = dx * dy;

      for (int iy = 0; iy < rd; ++iy) {
        const int y0 = yb + dil * iy;
        const int y1 = y0 + 1;
        const bool vy0 = y0 >= 0 && y0 < H2;
        const bool vy1 = y1 >= 0 && y1 < H2;
        const int64_t row0 = vy0 ? (int64_t)y0 * W2 : 0;
        const int64_t row1 = vy1 ? (int64_t)y1 * W2 : 0;

        for (int ix = 0; ix < rd; ++ix) {
          const int x0 = xb + dil * ix;
          const int x1 = x0 + 1;
          const bool vx0 = x0 >= 0 && x0 < W2;
          const bool vx1 = x1 >= 0 && x1 < W2;
          const bool la = vy0 && vx0;
          const bool lb = vy0 && vx1;
          const bool lc = vy1 && vx0;
          const bool ld = vy1 && vx1;

          // Displacement index: same channel order as the forward.
          const int d = YMAJOR ? (ix + rd * iy) : (iy + rd * ix);
          const float g =
              static_cast<float>(lvl_base[(int64_t)d * HW + p]);
          if (g == 0.f)
            continue; // dense grads never skip; sparse ones do

          for (int c = lane; c < C; c += LCORR_WARP_SIZE) {
            const float f1v = f1w[c];
            float va = 0.f, vb = 0.f, vc = 0.f, vd = 0.f;
            if (la) va = static_cast<float>(f2_lvl[(row0 + x0) * C + c]);
            if (lb) vb = static_cast<float>(f2_lvl[(row0 + x1) * C + c]);
            if (lc) vc = static_cast<float>(f2_lvl[(row1 + x0) * C + c]);
            if (ld) vd = static_cast<float>(f2_lvl[(row1 + x1) * C + c]);

            // Gradient of this pixel's fmap1 row: sum_d g * f2_interp.
            const float f2v = wa * va + wb * vb + wc * vc + wd * vd;
            f1gw[c] += g * f2v;

            // Scatter g * f1 to the four bilinear corners (fp32 atomics).
            const float gf1 = g * f1v;
            if (la)
              sycl::atomic_ref<float, sycl::memory_order::relaxed,
                               sycl::memory_scope::device,
                               sycl::access::address_space::global_space>(
                  f2g_lvl[(row0 + x0) * C + c])
                  .fetch_add(gf1 * wa);
            if (lb)
              sycl::atomic_ref<float, sycl::memory_order::relaxed,
                               sycl::memory_scope::device,
                               sycl::access::address_space::global_space>(
                  f2g_lvl[(row0 + x1) * C + c])
                  .fetch_add(gf1 * wb);
            if (lc)
              sycl::atomic_ref<float, sycl::memory_order::relaxed,
                               sycl::memory_scope::device,
                               sycl::access::address_space::global_space>(
                  f2g_lvl[(row1 + x0) * C + c])
                  .fetch_add(gf1 * wc);
            if (ld)
              sycl::atomic_ref<float, sycl::memory_order::relaxed,
                               sycl::memory_scope::device,
                               sycl::access::address_space::global_space>(
                  f2g_lvl[(row1 + x1) * C + c])
                  .fetch_add(gf1 * wd);
          }
        }
      }
    }

    // Advance to the next level in the packed buffers.
    if (lvl + 1 < levels) {
      f2_lvl += (int64_t)C * lvl_h * lvl_w;
      f2g_lvl += (int64_t)C * lvl_h * lvl_w;
      lvl_h >>= 1;
      lvl_w >>= 1;
    }
  }
  // All warps finished accumulating before the cooperative store below.
  item_ct1.barrier();

  // Store the fmap1 gradients (each accumulator element is written by
  // exactly one warp, so no atomics are needed).
  for (int i = item_ct1.get_local_id(2); i < LCORR_PIXELS_PER_BLOCK * C;
       i += LCORR_THREADS_PER_BLOCK) {
    const int q = i / C;
    const int cc = i - q * C;
    if (q < npix) {
      const int pq = p0 + q;
      const int hq = pq / W1;
      const int wq = pq - hq * W1;
      fmap1_grad[(((int64_t)b * H1 + hq) * W1 + wq) * C + cc] =
          static_cast<scalar_t>(f1g_s[i]);
    }
  }
}

// ---------------------------------------------------------------------------
// Generic fallback for any C / radius / dilation: fmap1 staged in shared
// memory as float, one warp per pixel, lanes split channels with a strided
// loop and a scalar sub-group reduction. Direct port of the CUDA
// localcorr_pyramid_kernel_any with the shuffle butterfly replaced by
// reduce_over_group.
// ---------------------------------------------------------------------------
template <typename scalar_t, bool YMAJOR = false>
void localcorr_pyramid_kernel_any(
    sycl::nd_item<3> item_ct1,
    const scalar_t *__restrict__ fmap1,        // [B, H1, W1, C]
    const scalar_t *__restrict__ fmap2_packed, // [B, C*sum_i h_i*w_i]
    const scalar_t *__restrict__ coords,       // [B, 2, H1, W1] (x, y)
    scalar_t *__restrict__ corr,               // [B, levels, RD*RD, H1, W1]
    int H1, int W1, int C, int r, int levels, int dil, uint8_t *dpct_local) {
  auto smem = (float *)dpct_local;
  const int rd = 2 * r + 1;
  const int RD2 = rd * rd;
  constexpr int LCORR_PIXELS_PER_BLOCK =
      LCORR_WARPS_PER_BLOCK; // 1 pixel per warp
  float *out_s = smem;       // [RD2, PIXELS_PER_BLOCK]
  float *f1_s = smem + RD2 * LCORR_PIXELS_PER_BLOCK; // [PIXELS, C]

  const int b = item_ct1.get_group(1);
  const int warp = item_ct1.get_local_id(2) >> 5;
  const int lane = item_ct1.get_local_id(2) & (LCORR_WARP_SIZE - 1);
  const int HW = H1 * W1;
  const int p0 = item_ct1.get_group(2) * LCORR_PIXELS_PER_BLOCK;
  const int npix = sycl::min(LCORR_PIXELS_PER_BLOCK, HW - p0);

  // Stage fmap1 for the pixels of this block (converted to float).
  for (int i = item_ct1.get_local_id(2); i < LCORR_PIXELS_PER_BLOCK * C;
       i += LCORR_THREADS_PER_BLOCK) {
    const int q = i / C;
    const int cc = i - q * C;
    float v = 0.f;
    if (q < npix) {
      const int pq = p0 + q;
      const int hq = pq / W1;
      const int wq = pq - hq * W1;
      v = static_cast<float>(
          fmap1[(((int64_t)b * H1 + hq) * W1 + wq) * C + cc]);
    }
    f1_s[i] = v;
  }
  item_ct1.barrier();

  int64_t f2_batch_elems = 0;
  {
    int lh = H1, lw = W1;
    for (int i = 0; i < levels; ++i) {
      f2_batch_elems += (int64_t)C * lh * lw;
      lh >>= 1;
      lw >>= 1;
    }
  }
  const scalar_t *f2_lvl = fmap2_packed + (int64_t)b * f2_batch_elems;
  int lvl_h = H1;
  int lvl_w = W1;

  for (int lvl = 0; lvl < levels; ++lvl) {
    const int H2 = lvl_h;
    const int W2 = lvl_w;
    const int p = p0 + warp; // LCORR_PIXELS_PER_WARP == 1

    if (p < HW) {
      const int q = warp;
      const float *f1w = f1_s + q * C;

      const scalar_t *cptr = coords + ((int64_t)b * 2 * HW) + p;
      const float clx = static_cast<float>(cptr[0]) / (float)(1 << lvl);
      const float cly = static_cast<float>(cptr[HW]) / (float)(1 << lvl);

      const float x0f = sycl::floor((float)clx);
      const float y0f = sycl::floor((float)cly);
      const float dx = clx - x0f;
      const float dy = cly - y0f;
      const int xb = static_cast<int>(x0f) - r * dil;
      const int yb = static_cast<int>(y0f) - r * dil;

      const float wa = (1.f - dx) * (1.f - dy);
      const float wb = dx * (1.f - dy);
      const float wc = (1.f - dx) * dy;
      const float wd = dx * dy;

      for (int iy = 0; iy < rd; ++iy) {
        const int y0 = yb + dil * iy;
        const int y1 = y0 + 1;
        const bool vy0 = y0 >= 0 && y0 < H2;
        const bool vy1 = y1 >= 0 && y1 < H2;
        const int64_t row0 = vy0 ? (int64_t)y0 * W2 : 0;
        const int64_t row1 = vy1 ? (int64_t)y1 * W2 : 0;

        for (int ix = 0; ix < rd; ++ix) {
          const int x0 = xb + dil * ix;
          const int x1 = x0 + 1;
          const bool vx0 = x0 >= 0 && x0 < W2;
          const bool vx1 = x1 >= 0 && x1 < W2;
          const bool la = vy0 && vx0;
          const bool lb = vy0 && vx1;
          const bool lc = vy1 && vx0;
          const bool ld = vy1 && vx1;

          float partial = 0.f;
          for (int c = lane; c < C; c += LCORR_WARP_SIZE) {
            float va = 0.f, vb = 0.f, vc = 0.f, vd = 0.f;
            if (la) va = static_cast<float>(f2_lvl[(row0 + x0) * C + c]);
            if (lb) vb = static_cast<float>(f2_lvl[(row0 + x1) * C + c]);
            if (lc) vc = static_cast<float>(f2_lvl[(row1 + x0) * C + c]);
            if (ld) vd = static_cast<float>(f2_lvl[(row1 + x1) * C + c]);
            partial += f1w[c] * (wa * va + wb * vb + wc * vc + wd * vd);
          }

          const float red = sycl::reduce_over_group(
              item_ct1.get_sub_group(), partial, sycl::plus<float>());

          const int d = YMAJOR ? (ix + rd * iy) : (iy + rd * ix);
          if (lane == 0)
            out_s[d * LCORR_PIXELS_PER_BLOCK + q] = red;
        }
      }
    }
    item_ct1.barrier();

    scalar_t *out_lvl = corr + ((int64_t)b * levels + lvl) * RD2 * HW;
    for (int i = item_ct1.get_local_id(2); i < RD2 * LCORR_PIXELS_PER_BLOCK;
         i += LCORR_THREADS_PER_BLOCK) {
      const int d = i / LCORR_PIXELS_PER_BLOCK;
      const int q = i - d * LCORR_PIXELS_PER_BLOCK;
      if (q < npix)
        out_lvl[(int64_t)d * HW + p0 + q] = static_cast<scalar_t>(out_s[i]);
    }
    item_ct1.barrier();

    if (lvl + 1 < levels) {
      f2_lvl += (int64_t)C * lvl_h * lvl_w;
      lvl_h >>= 1;
      lvl_w >>= 1;
    }
  }
}


// Submit helper: launches a kernel lambda on a (1, batch, blocks_x*T) grid
// with T = LCORR_THREADS_PER_BLOCK work-items per group. When smem_bytes >
// 0 the kernel lambda additionally receives a pointer to dynamic local
// memory. All kernels need a 32-lane sub-group (LCORR_WARP_SIZE) for their
// channel-split layouts and reductions.
template <typename KernelLambda, int SG_SIZE = 32>
static inline void lcorr_submit(sycl::queue *stream, size_t blocks_x,
                                size_t batch, size_t smem_bytes,
                                KernelLambda kfn) {
  stream->submit([&](sycl::handler &cgh) {
    const sycl::range<3> local_r(1, 1, LCORR_THREADS_PER_BLOCK);
    const sycl::range<3> global_r(1, batch,
                                  blocks_x * LCORR_THREADS_PER_BLOCK);
    if (smem_bytes > 0) {
      sycl::local_accessor<uint8_t, 1> smem_acc(sycl::range<1>(smem_bytes),
                                                cgh);
      cgh.parallel_for(
          sycl::nd_range<3>(global_r, local_r),
          [=](sycl::nd_item<3> item) [[sycl::reqd_sub_group_size(SG_SIZE)]] {
            kfn(item,
                smem_acc.get_multi_ptr<sycl::access::decorated::no>().get());
          });
    } else {
      cgh.parallel_for(
          sycl::nd_range<3>(global_r, local_r),
          [=](sycl::nd_item<3> item) [[sycl::reqd_sub_group_size(SG_SIZE)]] {
            kfn(item, nullptr);
          });
    }
  });
}

// Maximum channels per lane of the g8 (8-lanes-per-pixel) GPU fast path.
#define LCORR_G8_NELEM_MAX 32


// ---------------------------------------------------------------------------
// GPU fast path A (8 lanes per pixel): direct port of the CUDA
// localcorr_pyramid_kernel_g8. Lanes are split into groups of 8; each
// group owns one output pixel and each lane owns C/8 consecutive
// channels, so corner loads are wide and only 3 shuffle steps are needed
// per butterfly. Whole displacement rows are reduced with one interleaved
// butterfly; every lane of the group ends up with all reduced values, so
// the stores are strided by the group size. GPU only: uses
// sycl::permute_group_by_xor, which crashes the Intel OpenCL CPU runtime.
// ---------------------------------------------------------------------------
template <typename scalar_t, int NMAX, int RADIUS, bool YMAJOR,
          bool FULL = false>
void localcorr_pyramid_kernel_g8(
    sycl::nd_item<3> item_ct1,
    const scalar_t *__restrict__ fmap1,        // [B, H1, W1, C]
    const scalar_t *__restrict__ fmap2_packed, // [B, C*sum_i h_i*w_i]
    const scalar_t *__restrict__ coords,       // [B, 2, H1, W1] (x, y)
    scalar_t *__restrict__ corr,               // [B, levels, RD*RD, H1, W1]
    int H1, int W1, int C, int levels) {
  constexpr int LANES_PER_PIXEL = 8;
  constexpr int RD = 2 * RADIUS + 1;
  constexpr int RD2 = RD * RD;
  constexpr int PIXELS_PER_WARP = LCORR_WARP_SIZE / LANES_PER_PIXEL;

  const int b = item_ct1.get_group(1);
  const int warp = item_ct1.get_local_id(2) >> 5;
  const int lane = item_ct1.get_local_id(2) & (LCORR_WARP_SIZE - 1);
  const int lgrp = lane / LANES_PER_PIXEL;  // pixel within the warp
  const int lhalf = lane % LANES_PER_PIXEL; // lane within the group
  const int HW = H1 * W1;
  const int p = item_ct1.get_group(2) * (LCORR_WARPS_PER_BLOCK *
                                         PIXELS_PER_WARP) +
                warp * PIXELS_PER_WARP + lgrp;
  const bool valid = p < HW;
  const int NELEM = C / LANES_PER_PIXEL; // channels per lane (runtime)

  // Per-level sizes of the packed fmap2 buffer (batch-major layout:
  // [B, C*sum_i h_i*w_i], level i of batch b at b*P + C*sum_{j<i} h_j*w_j).
  int64_t f2_batch_elems = 0;
  {
    int lh = H1, lw = W1;
    for (int i = 0; i < levels; ++i) {
      f2_batch_elems += (int64_t)C * lh * lw;
      lh >>= 1;
      lw >>= 1;
    }
  }
  const scalar_t *f2_lvl = fmap2_packed + (int64_t)b * f2_batch_elems;
  int lvl_h = H1;
  int lvl_w = W1;

  // ---- Load fmap1 for this pixel into registers (float math). ----
  float f1_reg[NMAX];
  if (valid) {
    const int h1 = p / W1;
    const int w1 = p - h1 * W1;
    const scalar_t *f1ptr =
        fmap1 + (((int64_t)b * H1 + h1) * W1 + w1) * C + lhalf * NELEM;
    if constexpr (FULL) {
      #pragma unroll
      for (int i = 0; i < NMAX; ++i)
        f1_reg[i] = static_cast<float>(f1ptr[i]);
    } else {
      #pragma unroll
      for (int i = 0; i < NMAX; ++i)
        f1_reg[i] = (i < NELEM) ? static_cast<float>(f1ptr[i]) : 0.f;
    }
  } else {
    #pragma unroll
    for (int i = 0; i < NMAX; ++i) f1_reg[i] = 0.f;
  }

  // Level-0 coordinates of this pixel.
  float cx = 0.f, cy = 0.f;
  if (valid) {
    const scalar_t *cptr = coords + ((int64_t)b * 2 * HW) + p;
    cx = static_cast<float>(cptr[0]);   // x
    cy = static_cast<float>(cptr[HW]);  // y
  }

  for (int lvl = 0; lvl < levels; ++lvl) {
    // Level coordinates are halved every level.
    const float clx = cx / (float)(1 << lvl);
    const float cly = cy / (float)(1 << lvl);

    const int H2 = lvl_h;
    const int W2 = lvl_w;

    const float x0f = sycl::floor((float)clx);
    const float y0f = sycl::floor((float)cly);
    const float dx = clx - x0f;
    const float dy = cly - y0f;
    const int xb = static_cast<int>(x0f) - RADIUS;
    const int yb = static_cast<int>(y0f) - RADIUS;

    const float wa = (1.f - dx) * (1.f - dy);
    const float wb = dx * (1.f - dy);
    const float wc = (1.f - dx) * dy;
    const float wd = dx * dy;

    scalar_t *out_lvl = corr + ((int64_t)b * levels + lvl) * RD2 * HW;

    // Predicated corner load: column x of row `row` (or zeros) into the
    // NELEM channels of this lane.
    auto loadCorner = [&](int64_t row, int x, bool vy, bool vx, float *fa) {
      if (vy && vx) {
        const scalar_t *q = f2_lvl + (row + x) * C + lhalf * NELEM;
        if constexpr (FULL) {
          #pragma unroll
          for (int i = 0; i < NMAX; ++i)
            fa[i] = static_cast<float>(q[i]);
        } else {
          #pragma unroll
          for (int i = 0; i < NMAX; ++i)
            fa[i] = (i < NELEM) ? static_cast<float>(q[i]) : 0.f;
        }
      } else {
        #pragma unroll
        for (int i = 0; i < NMAX; ++i) fa[i] = 0.f;
      }
    };

    #pragma unroll
    for (int iy = 0; iy < RD; ++iy) {
      const int y0 = yb + iy;
      const int y1 = y0 + 1;
      const bool vy0 = y0 >= 0 && y0 < H2;
      const bool vy1 = y1 >= 0 && y1 < H2;
      const int64_t row0 = vy0 ? (int64_t)y0 * W2 : 0;
      const int64_t row1 = vy1 ? (int64_t)y1 * W2 : 0;

      // Corner windows: a/c = column x0 (rows y0/y1), b/d = column x1.
      float ca_a[NMAX], cb_a[NMAX], cc_a[NMAX], cd_a[NMAX];
      const bool vx0 = xb >= 0 && xb < W2;
      const bool vx1 = xb + 1 >= 0 && xb + 1 < W2;
      loadCorner(row0, xb, vy0, vx0, ca_a);
      loadCorner(row1, xb, vy1, vx0, cc_a);
      loadCorner(row0, xb + 1, vy0, vx1, cb_a);
      loadCorner(row1, xb + 1, vy1, vx1, cd_a);

      // Per-displacement partial dot products of this window row.
      float partial[RD];

      #pragma unroll
      for (int ix = 0; ix < RD; ++ix) {
        float sum = 0.f;
        #pragma unroll
        for (int i = 0; i < NMAX; ++i) {
          const float f2v = wa * ca_a[i] + wb * cb_a[i] + wc * cc_a[i] +
                            wd * cd_a[i];
          sum = sycl::fma(f1_reg[i], f2v, sum);
        }
        partial[ix] = sum;

        // Slide the window (the x1 corners become the next x0 corners)
        // and prefetch the next x1 column (1-deep prefetch).
        #pragma unroll
        for (int i = 0; i < NMAX; ++i) {
          ca_a[i] = cb_a[i];
          cc_a[i] = cd_a[i];
        }
        const int xnext = xb + ix + 2;
        const bool vxn = xnext >= 0 && xnext < W2;
        loadCorner(row0, xnext, vy0, vxn, cb_a);
        loadCorner(row1, xnext, vy1, vxn, cd_a);
      }

      // Interleaved butterfly within the 8-lane group; afterwards every
      // lane of the group holds every reduced partial[ix].
      #pragma unroll
      for (int off = LANES_PER_PIXEL / 2; off > 0; off >>= 1) {
        #pragma unroll
        for (int ix = 0; ix < RD; ++ix)
          partial[ix] += sycl::permute_group_by_xor(
              item_ct1.get_sub_group(), partial[ix], off);
      }

      // Strided direct stores (lane lhalf stores displacements
      // lhalf, lhalf+8, ...). Displacement index: d = iy + rd*ix
      // (YMAJOR: d = ix + rd*iy).
      if (valid) {
        #pragma unroll
        for (int ix = lhalf; ix < RD; ix += LANES_PER_PIXEL) {
          const int d = YMAJOR ? (ix + RD * iy) : (iy + RD * ix);
          out_lvl[(int64_t)d * HW + p] = static_cast<scalar_t>(partial[ix]);
        }
      }
    }

    // Advance to the next level in the packed buffer.
    if (lvl + 1 < levels) {
      f2_lvl += (int64_t)C * lvl_h * lvl_w;
      lvl_h >>= 1;
      lvl_w >>= 1;
    }
  }
}


template <typename scalar_t, bool YM>
static bool localcorr_pyramid_dispatch(const void *fmap1,
                                        const void *fmap2_packed,
                                        const void *coords, void *corr, int H1,
                                        int W1, int C, int radius, int levels,
                                        int dil, int batch,
                                        sycl::queue *stream) {
  try {
    const size_t HW = (size_t)H1 * W1;

    // GPU fast path (g8): 8 lanes per output pixel, lanes split the
    // channels (NELEM = C/8), butterfly reductions with
    // sycl::permute_group_by_xor inside the 8-lane group only (3 shuffle
    // steps). This is the direct port of the CUDA g8 kernel and is by far
    // the fastest layout for small C (e.g. C=32: 4 channels/lane instead
    // of a 32-lane reduction per displacement). permute_group_by_xor
    // crashes the Intel OpenCL CPU runtime, so this path is only taken
    // when the queue's device is a GPU.
    if (stream->get_device().is_gpu() && C % 8 == 0 && (C / 8) >= 1 &&
        (C / 8) <= LCORR_G8_NELEM_MAX && radius >= 1 &&
        radius <= LCORR_MAX_RADIUS && dil == 1) {
      const int nelem = C / 8;
      constexpr int G8_PPB =
          LCORR_WARPS_PER_BLOCK * (LCORR_WARP_SIZE / 8); // 16 pixels/block
      const size_t g8_blocks_x = (HW + G8_PPB - 1) / G8_PPB;
      auto launch_g8 = [&](auto nmaxconst, auto rconst, auto fullconst) {
        constexpr int NMAX = decltype(nmaxconst)::value;
        constexpr int RADIUS_C = decltype(rconst)::value;
        constexpr bool FULL_C = decltype(fullconst)::value;
        auto kfn = [=](sycl::nd_item<3> item, uint8_t *) {
          localcorr_pyramid_kernel_g8<scalar_t, NMAX, RADIUS_C, YM, FULL_C>(
              item, static_cast<const scalar_t *>(fmap1),
              static_cast<const scalar_t *>(fmap2_packed),
              static_cast<const scalar_t *>(coords),
              static_cast<scalar_t *>(corr), H1, W1, C, levels);
        };
        lcorr_submit<decltype(kfn), 8>(stream, g8_blocks_x, batch, 0, kfn);
      };
      // FULL: NELEM fills the register array exactly (C/8 is a power of
      // two), so the corner loads need no runtime guards and vectorize.
      auto launch_nmax = [&](auto rconst) {
        if (nelem <= 4) {
          if (nelem == 4)
            launch_g8(std::integral_constant<int, 4>{}, rconst,
                      std::true_type{});
          else
            launch_g8(std::integral_constant<int, 4>{}, rconst,
                      std::false_type{});
        } else if (nelem <= 8) {
          if (nelem == 8)
            launch_g8(std::integral_constant<int, 8>{}, rconst,
                      std::true_type{});
          else
            launch_g8(std::integral_constant<int, 8>{}, rconst,
                      std::false_type{});
        } else if (nelem <= 16) {
          if (nelem == 16)
            launch_g8(std::integral_constant<int, 16>{}, rconst,
                      std::true_type{});
          else
            launch_g8(std::integral_constant<int, 16>{}, rconst,
                      std::false_type{});
        } else {
          if (nelem == 32)
            launch_g8(std::integral_constant<int, 32>{}, rconst,
                      std::true_type{});
          else
            launch_g8(std::integral_constant<int, 32>{}, rconst,
                      std::false_type{});
        }
      };
      switch (radius) {
        case 1:
          launch_nmax(std::integral_constant<int, 1>{});
          break;
        case 2:
          launch_nmax(std::integral_constant<int, 2>{});
          break;
        case 3:
          launch_nmax(std::integral_constant<int, 3>{});
          break;
        default:
          launch_nmax(std::integral_constant<int, 4>{});
          break;
      }
      return true;
    }

    // Fast path: C divisible by 32 with at most LCORR_NELEM_MAX channels
    // per lane, compile-time radius in [1, 4], unit dilation. The half
    // variant is limited to 4 channels per lane (C <= 128): the Intel
    // OpenCL CPU runtime's compiler hangs on the larger half kernels, so
    // those shapes take the generic fallback instead.
    constexpr int MAX_FAST_NELEM =
        (sizeof(scalar_t) == 2) ? 4 : LCORR_NELEM_MAX;
    const int nelem = C / LCORR_WARP_SIZE;
    const bool use_fast = C % LCORR_WARP_SIZE == 0 && nelem >= 1 &&
                          nelem <= MAX_FAST_NELEM && radius >= 1 &&
                          radius <= LCORR_MAX_RADIUS && dil == 1;

    if (use_fast) {
      const size_t blocks_x = (HW + LCORR_WARPS_PER_BLOCK - 1) /
                              LCORR_WARPS_PER_BLOCK;
      auto launch_fast = [&](auto nmaxconst, auto rconst) {
        constexpr int NMAX = decltype(nmaxconst)::value;
        constexpr int RADIUS_C = decltype(rconst)::value;
        auto kfn = [=](sycl::nd_item<3> item, uint8_t *) {
          localcorr_pyramid_kernel<scalar_t, NMAX, RADIUS_C, YM>(
              item, static_cast<const scalar_t *>(fmap1),
              static_cast<const scalar_t *>(fmap2_packed),
              static_cast<const scalar_t *>(coords),
              static_cast<scalar_t *>(corr), H1, W1, C, levels);
        };
        lcorr_submit(stream, blocks_x, batch, 0, kfn);
      };
      auto launch_nmax = [&](auto rconst) {
        if (nelem <= 4) {
          launch_fast(std::integral_constant<int, 4>{}, rconst);
        } else if (nelem <= 8) {
          launch_fast(std::integral_constant<int, 8>{}, rconst);
        } else {
          launch_fast(std::integral_constant<int, 16>{}, rconst);
        }
      };
      switch (radius) {
        case 1:
          launch_nmax(std::integral_constant<int, 1>{});
          break;
        case 2:
          launch_nmax(std::integral_constant<int, 2>{});
          break;
        case 3:
          launch_nmax(std::integral_constant<int, 3>{});
          break;
        default:
          launch_nmax(std::integral_constant<int, 4>{});
          break;
      }
      return true;
    }

    // Generic fallback: any C, runtime radius/dilation, shared-memory
    // staging of fmap1.
    constexpr int ANY_PPB = LCORR_WARPS_PER_BLOCK; // 1 pixel per warp
    const size_t blocks_x = (HW + ANY_PPB - 1) / ANY_PPB;
    const size_t out_smem = (size_t)(2 * radius + 1) * (2 * radius + 1) *
                            ANY_PPB * sizeof(float);
    const size_t smem_bytes = out_smem + (size_t)ANY_PPB * C * sizeof(float);
    if (smem_bytes > 99 * 1024) {
      return false;
    }
    auto kfn = [=](sycl::nd_item<3> item, uint8_t *smem) {
      localcorr_pyramid_kernel_any<scalar_t, YM>(
          item, static_cast<const scalar_t *>(fmap1),
          static_cast<const scalar_t *>(fmap2_packed),
          static_cast<const scalar_t *>(coords),
          static_cast<scalar_t *>(corr), H1, W1, C, radius, levels, dil,
          smem);
    };
    lcorr_submit(stream, blocks_x, batch, smem_bytes, kfn);
    return true;
  } catch (const sycl::exception &e) {
    std::fprintf(stderr, "localcorr SYCL launch error: %s\n", e.what());
    return false;
  }
}

extern "C" bool launchLocalCorrCudaPyramidForward(
    const void *fmap1, const void *fmap2_packed, const void *coords, void *corr,
    int B, int H1, int W1, int C, int radius, int levels, int dilation,
    bool isHalf, bool ymajor, sycl::queue *stream) {
  const int HW = H1 * W1;
  if (HW <= 0 || B <= 0) {
    return true;
  }
  if (levels < 1 || levels > LCORR_MAX_LEVELS) {
    return false;
  }
  if (dilation < 1) {
    return false;
  }
  // Every level must have at least one pixel.
  for (int lvl = 0; lvl < levels; ++lvl) {
    if ((H1 >> lvl) < 1 || (W1 >> lvl) < 1) {
      return false;
    }
  }

  if (!isHalf) {
    if (ymajor) {
      return localcorr_pyramid_dispatch<float, true>(
          fmap1, fmap2_packed, coords, corr, H1, W1, C, radius, levels,
          dilation, B, stream);
    }
    return localcorr_pyramid_dispatch<float, false>(
        fmap1, fmap2_packed, coords, corr, H1, W1, C, radius, levels, dilation,
        B, stream);
  }
  if (ymajor) {
    return localcorr_pyramid_dispatch<sycl::half, true>(
        fmap1, fmap2_packed, coords, corr, H1, W1, C, radius, levels, dilation,
        B, stream);
  }
  return localcorr_pyramid_dispatch<sycl::half, false>(
      fmap1, fmap2_packed, coords, corr, H1, W1, C, radius, levels, dilation,
      B, stream);
}

// Backward dispatch: a single generic kernel (any C, runtime
// radius/dilation, all levels fused). fmap2_grad is always an fp32
// accumulator (see the header contract).
template <typename scalar_t, bool YM>
static bool localcorr_pyramid_backward_dispatch(
    const void *fmap1, const void *fmap2_packed, const void *coords,
    const void *corr_grad, void *fmap1_grad, float *fmap2_grad, int H1, int W1,
    int C, int radius, int levels, int dil, int batch,
    sycl::queue *stream) {
  try {
    constexpr int PPB = LCORR_WARPS_PER_BLOCK; // 1 pixel per warp
    const size_t HW = (size_t)H1 * W1;
    const size_t blocks_x = (HW + PPB - 1) / PPB;
    const size_t smem_bytes =
        (size_t)2 * PPB * C * sizeof(float); // f1_s + f1g_s
    if (smem_bytes > 99 * 1024) {
      return false;
    }
    auto kfn = [=](sycl::nd_item<3> item, uint8_t *smem) {
      localcorr_pyramid_backward_kernel<scalar_t, YM>(
          item, static_cast<const scalar_t *>(fmap1),
          static_cast<const scalar_t *>(fmap2_packed),
          static_cast<const scalar_t *>(coords),
          static_cast<const scalar_t *>(corr_grad),
          static_cast<scalar_t *>(fmap1_grad), fmap2_grad, H1, W1, C, radius,
          levels, dil, smem);
    };
    lcorr_submit(stream, blocks_x, batch, smem_bytes, kfn);
    return true;
  } catch (const sycl::exception &e) {
    std::fprintf(stderr, "localcorr SYCL backward launch error: %s\n", e.what());
    return false;
  }
}

extern "C" bool launchLocalCorrCudaPyramidBackward(
    const void *fmap1, const void *fmap2_packed, const void *coords,
    const void *corr_grad, void *fmap1_grad, float *fmap2_grad, int B, int H1,
    int W1, int C, int radius, int levels, int dilation, bool isHalf,
    bool ymajor, sycl::queue *stream) {
  const int HW = H1 * W1;
  if (HW <= 0 || B <= 0) {
    return true;
  }
  if (levels < 1 || levels > LCORR_MAX_LEVELS) {
    return false;
  }
  if (dilation < 1) {
    return false;
  }
  // Every level must have at least one pixel.
  for (int lvl = 0; lvl < levels; ++lvl) {
    if ((H1 >> lvl) < 1 || (W1 >> lvl) < 1) {
      return false;
    }
  }

  if (!isHalf) {
    if (ymajor) {
      return localcorr_pyramid_backward_dispatch<float, true>(
          fmap1, fmap2_packed, coords, corr_grad, fmap1_grad, fmap2_grad, H1,
          W1, C, radius, levels, dilation, B, stream);
    }
    return localcorr_pyramid_backward_dispatch<float, false>(
        fmap1, fmap2_packed, coords, corr_grad, fmap1_grad, fmap2_grad, H1, W1,
        C, radius, levels, dilation, B, stream);
  }
  if (ymajor) {
    return localcorr_pyramid_backward_dispatch<sycl::half, true>(
        fmap1, fmap2_packed, coords, corr_grad, fmap1_grad, fmap2_grad, H1, W1,
        C, radius, levels, dilation, B, stream);
  }
  return localcorr_pyramid_backward_dispatch<sycl::half, false>(
      fmap1, fmap2_packed, coords, corr_grad, fmap1_grad, fmap2_grad, H1, W1, C,
      radius, levels, dilation, B, stream);
}
